I-UX","name":"area/UI-UX","color":"006b75","default":false,"description":null},{"id":276558995,"node_id":"MDU6TGFiZWwyNzY1NTg5OTU=","url":"https://api.github.com/repos/galaxyproject/galaxy/labels/area/workflows","name":"area/workflows","color":"006b75","default":false,"description":null},{"id":7510441968,"node_id":"LA_kwDOAdw-Nc8AAAABv6g_8A","url":"https://api.github.com/repos/galaxyproject/galaxy/labels/BRC","name":"BRC","color":"1AF76A","default":false,"description":"Items related to BRC-analytics"}],"state":"open","locked":false,"assignee":null,"assignees":[],"milestone":null,"comments":0,"created_at":"2024-12-05T18:21:25Z","updated_at":"2024-12-05T18:21:25Z","closed_at":null,"author_association":"MEMBER","active_lock_reason":null,"body":"If you use an external site (like https://iwc.galaxyproject.org/ or BRC analytics) to land on the workflow run form in a Galaxy server, that workflow gets added to your workflow list:
![image](https://github.com/user-attachments/assets/db5ad865-a843-4ca4-9549-3512ef20d6fc)

If you delete this workflow, the next time you use that same external site to then land on the same workflow run form in Galaxy, you won't be able to run it (since Galaxy wouldn't have reimported that workflow, and will try to reuse the existing, albeit deleted one):
